import sys

def main():
    lines = sys.stdin.read().split('\n')
    n = int(lines[0])
    titles = [''.join(lines[1 + i].split()).lower() for i in range(n)]
    owners = {}
    for i, t in enumerate(titles):
        L = len(t)
        for a in range(L):
            for b in range(a + 1, L + 1):
                s = t[a:b]
                o = owners.get(s)
                if o is None:
                    owners[s] = i
                elif o != i:
                    owners[s] = -1
    out = []
    for i, t in enumerate(titles):
        L = len(t)
        best = None
        for length in range(1, L + 1):
            for a in range(L - length + 1):
                s = t[a:a + length]
                if owners[s] == i and (best is None or s < best):
                    best = s
            if best is not None:
                break
        out.append(best if best is not None else '-1')
    print('\n'.join(out))

main()

