def gen(rng):
    def fmt(ts):
        return str(len(ts)) + '\n' + '\n'.join(ts)

    def spaced(word):
        # insert random single spaces and random capitalisation
        out = []
        for ch in word:
            if out and rng.random() < 0.12:
                out.append(' ')
            out.append(ch.upper() if rng.random() < 0.3 else ch)
        return ''.join(out)

    tests = [
        fmt(['Abc']),
        fmt(['a', 'a']),
        fmt(['ab', 'ba']),
        fmt(['abc', 'a b c', 'ABC']),
        fmt(['cab', 'ad', 'bad', 'c']),
        fmt(['a b', 'ab c', 'abcd']),
        fmt(['x', 'y', 'z']),
        fmt(['aaa', 'aa', 'a']),
        fmt(['The Phantom Menace', 'Attack of the Clones', 'Revenge of the Sith', 'A New Hope',
             'The Empire Strikes Back', 'The Return of the Jedi', 'The Force Awakens', 'The Last Jedi']),
    ]
    for alpha, maxn, maxl in (('ab', 4, 6), ('abc', 5, 8), ('abcd', 6, 10), ('abcdefgh', 8, 12), ('ab', 8, 10), ('abc', 3, 6)):
        for _ in range(3):
            n = rng.randint(1, maxn)
            ts = []
            for _ in range(n):
                w = ''.join(rng.choice(alpha) for _ in range(rng.randint(1, maxl)))
                ts.append(spaced(w))
            tests.append(fmt(ts))
    for alpha in ('ab', 'abc', 'abcdefghijklmnopqrstuvwxyz', 'abcdefgh'):
        ts = []
        for _ in range(100):
            w = ''.join(rng.choice(alpha) for _ in range(rng.randint(15, 20)))
            ts.append(spaced(w)[:30].strip() or 'a')
        tests.append(fmt(ts))
    ts = ['a' * 20 for _ in range(100)]
    tests.append(fmt(ts))
    ts = ['a' * rng.randint(1, 20) for _ in range(100)]
    tests.append(fmt(ts))
    return tests

